  ('00000000-0000-4000-8004-000000000001', '00000000-0000-4000-8002-000000000001', 'BLOG', 'revisar «5 hábitos para una piel saludable» y confirmar la idea pendiente.'),
  ('00000000-0000-4000-8004-000000000002', '00000000-0000-4000-8002-000000000001', 'REDES_SOCIALES', 'revisar «Tu ritual, tu momento» y «Un minuto para cuidarte».'),
