  ('00000000-0000-4000-8005-000000000001', 1, 'AGENTE', NULL, 'Agente de Contenido', '{"tipo":"COPY","red":"Instagram","copy":"Bienvenido, octubre. Un momento para ti, todos los días. 🌿","hashtags":["#CasaOliva","#CuidadoConsciente"],"cta":"Descubre tu ritual","sugerenciaVisual":"Producto sobre piedra con ramas de olivo, luz cálida.","enfoque":"Bienestar cotidiano"}'::jsonb, '2026-10-01T13:00:00Z', '00000000-0000-4000-8001-000000000003', '2026-10-01T13:00:00Z'),
  ('00000000-0000-4000-8005-000000000002', 1, 'PERSONA', '00000000-0000-4000-8001-000000000003', NULL, '{"tipo":"COPY","red":"Facebook","copy":"Tu pausa de cada día. Un momento para ti, todos los días. 🌿","hashtags":["#CasaOliva","#CuidadoConsciente"],"cta":"Descubre tu ritual","sugerenciaVisual":"Producto sobre piedra con ramas de olivo, luz cálida.","enfoque":"Bienestar cotidiano"}'::jsonb, '2026-10-01T13:00:00Z', '00000000-0000-4000-8001-000000000003', '2026-10-01T13:00:00Z'),
  ('00000000-0000-4000-8005-000000000003', 1, 'AGENTE', NULL, 'Agente Editorial', '{"tipo":"BLOG","tituloSeo":"Cómo encontrar tu ritual diario","metaDescripcion":"Cómo encontrar tu ritual diario","slug":"como-encontrar-tu-ritual-diario","cuerpoMd":"# Cómo encontrar tu ritual diario\n\nCuidar la piel no exige rutinas largas: exige constancia. En este artículo repasamos limpieza, hidratación, protección y descanso.\n\n## 1. Limpieza suave\n\nDos veces al día, con productos que respeten tu piel.\n\n## 2. Hidratación\n\nUn sérum ligero y una crema acorde a tu tipo de piel.","palabras":1340}'::jsonb, '2026-10-02T13:00:00Z', '00000000-0000-4000-8001-000000000003', '2026-10-02T13:00:00Z'),
