  ('00000000-0000-4000-8005-000000000015', 1, 'AGENTE', NULL, 'Agente de Contenido', '{"tipo":"COPY","red":"Facebook","copy":"Elige tu momento. Un momento para ti, todos los días. 🌿","hashtags":["#CasaOliva","#CuidadoConsciente"],"cta":"Descubre tu ritual","sugerenciaVisual":"Producto sobre piedra con ramas de olivo, luz cálida.","enfoque":"Bienestar cotidiano"}'::jsonb, '2026-10-20T13:00:00Z', '00000000-0000-4000-8001-000000000003', '2026-10-20T13:00:00Z'),
